import java.io.*;
import java.util.*;

public class Main {
    private static int calculate(char[] s, char x) {
        for(int i = 0; i < s.length; i++) {
            if(s[i] == 'X') s[i] = x;
        }
        if(s[0] == '0') return 0;
        int result = 1;
        boolean firstXEncountered = true;
        for(int i = 0; i < s.length; i++) {
            if(s[i] == '_') {
                result *= (i == 0) ? 9 : 10;
            } else if(s[i] == 'X' && firstXEncountered) {
                result *= (i == 0) ? 9 : 10;
                firstXEncountered = false;
            }
        }
        return result;
    }
    private static boolean isReplacePossible(char[] s, char a, char b) {
        if(s[s.length-2] >= '0' && s[s.length-2] <= '9' && s[s.length-2] != a) return false;
        if(s[s.length-1] >= '0' && s[s.length-1] <= '9' && s[s.length-1] != b) return false;
        if(s[s.length-2] == 'X' && s[s.length-1] == 'X' && a != b) return false;
        return true;
    }
    public static void main(String[] args) throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter writer = new PrintWriter(new OutputStreamWriter(System.out));
        char[] s = reader.readLine().toCharArray();
        if(s.length < 2) {
            writer.println((s[0] == '0' || s[0] == '_' || s[0] == 'X') ? 1 : 0);
        } else {
            int totalWays = 0;
            if(isReplacePossible(s, '0', '0')) {
                char[] t = s.clone();
                t[t.length-2] = '0';
                t[t.length-1] = '0';
                if(s[s.length-2] == 'X') {
                    totalWays += calculate(t, t[t.length-2]);
                } else if(s[s.length-1] == 'X') {
                    totalWays += calculate(t, t[t.length-1]);
                } else {
                    totalWays += calculate(t, 'X');
                }
            }
            if(isReplacePossible(s, '2', '5')) {
                char[] t = s.clone();
                t[t.length-2] = '2';
                t[t.length-1] = '5';
                if(s[s.length-2] == 'X') {
                    totalWays += calculate(t, t[t.length-2]);
                } else if(s[s.length-1] == 'X') {
                    totalWays += calculate(t, t[t.length-1]);
                } else {
                    totalWays += calculate(t, 'X');
                }
            }
            if(isReplacePossible(s, '5', '0')) {
                char[] t = s.clone();
                t[t.length-2] = '5';
                t[t.length-1] = '0';
                if(s[s.length-2] == 'X') {
                    totalWays += calculate(t, t[t.length-2]);
                } else if(s[s.length-1] == 'X') {
                    totalWays += calculate(t, t[t.length-1]);
                } else {
                    totalWays += calculate(t, 'X');
                }
            }
            if(isReplacePossible(s, '7', '5')) {
                char[] t = s.clone();
                t[t.length-2] = '7';
                t[t.length-1] = '5';
                if(s[s.length-2] == 'X') {
                    totalWays += calculate(t, t[t.length-2]);
                } else if(s[s.length-1] == 'X') {
                    totalWays += calculate(t, t[t.length-1]);
                } else {
                    totalWays += calculate(t, 'X');
                }
            }
            writer.println(totalWays);
        }
        reader.close();
        writer.close();
    }
}
